long long sumPositive(const int a[], int n, int &cnt) {
    long long sum = 0;
    cnt = 0;
    for (int i = 0; i < n; ++i) {
        if (a[i] > 0) {
            sum += a[i];
            ++cnt;
        }
    }
    return sum;
}

