int rowWithMaxSum(const int a[][MAX], int R, int C) {
    int bestRow = 0;
    long long bestSum = 0;
    for (int j = 0; j < C; ++j) bestSum += a[0][j];

    for (int i = 1; i < R; ++i) {
        long long sum = 0;
        for (int j = 0; j < C; ++j) sum += a[i][j];
        if (sum > bestSum) {
            bestSum = sum;
            bestRow = i;
        }
    }
    return bestRow;
}

